@js:
var b=String(baseUrl);
var m=b.match(/[?&]goto=([^&]+)/);
var t=m?decodeURIComponent(m[1]):b;
if(!t){t='https://ogfap.com/';}
t=t.replace(/#.*$/,'').replace(/["'<>\\]/g,function(c){return encodeURIComponent(c);});
var tn=t.replace(/^https?:\/\//,'').split('/')[0].replace(/[<>"']/g,'');
var P=[];
P.push('<!DOCTYPE html><html><head><meta charset="UTF-8">');
P.push('<meta name="viewport" content="width=device-width,initial-scale=1,minimum-scale=1,maximum-scale=1,user-scalable=no">');
P.push('<title>'+tn+'</title>');
P.push('<style>html,body{margin:0;padding:0;height:100%;background:#000;overflow:hidden}');
P.push('#f{position:fixed;top:0;left:0;width:100vw;height:100vh;border:0;background:#000;z-index:10}');
P.push('#bar{position:fixed;top:0;left:0;right:0;z-index:9999;background:rgba(15,18,24,.82);color:#cfd8dc;font:12px/28px sans-serif;padding:0 10px;display:flex;gap:12px;align-items:center;height:28px}');
P.push('#bar .n{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}');
P.push('#bar a{color:#8ab4f8;text-decoration:none;padding:0 6px}');
P.push('#bar.err{background:rgba(80,10,10,.92);color:#ff8a80}</style></head><body>');
P.push('<div id="bar"><span class="n">'+tn+' · 加载中…</span><a id="raw">原站</a><a id="rl">刷新</a><a id="hd">×</a></div>');
P.push('<iframe id="f" src="'+t+'" sandbox="allow-scripts allow-same-origin allow-forms allow-top-navigation-by-user-activation" allow="autoplay; fullscreen; encrypted-media" allowfullscreen referrerpolicy="no-referrer"></iframe>');
P.push('<script>');
P.push('var BAR=document.getElementById("bar"),N=BAR.querySelector(".n"),F=document.getElementById("f"),OK=false;');
P.push('F.addEventListener("load",function(){OK=true;BAR.classList.remove("err");N.textContent="'+tn+' · 已连接 · 点×隐藏";});');
P.push('document.getElementById("hd").onclick=function(){BAR.style.display="none";};');
P.push('document.getElementById("rl").onclick=function(){N.textContent="刷新中…";F.src=F.src};');
P.push('document.getElementById("raw").onclick=function(){location.replace("'+t+'")};');
P.push('setTimeout(function(){if(!OK){BAR.classList.add("err");N.textContent="加载超时或站点被墙 · 点[原站]直接打开试试";}},12000);');
P.push('<\/script></body></html>');
result=P.join('');
